239	static uint32_t kws_capture_isqrt(uint64_t value)
240	{
241	  uint64_t result = 0;
242	  uint64_t bit = (uint64_t)1 << 62;
243	
244	  while (bit > value)
245	    {
246	      bit >>= 2;
247	    }
248	
249	  while (bit != 0)
250	    {
251	      if (value >= result + bit)
252	        {
253	          value -= result + bit;
254	          result = (result >> 1) + bit;
255	        }
256	      else
257	        {
258	          result >>= 1;
259	        }
260	
261	      bit >>= 2;
262	    }
263	
264	  return (uint32_t)result;
265	}
