267	static int kws_capture_measure(FAR const char *path,
268	                               FAR struct kws_capture_metrics_s *metrics)
269	{
270	  int16_t samples[KWS_CAPTURE_FRAME_SAMPLES];
271	  ssize_t nread;
272	  int fd;
273	
274	  memset(metrics, 0, sizeof(*metrics));
275	  fd = open(path, O_RDONLY | O_CLOEXEC);
276	  if (fd < 0)
277	    {
278	      return -errno;
279	    }
280	
281	  while ((nread = read(fd, samples, sizeof(samples))) > 0)
282	    {
283	      size_t count;
284	      size_t i;
285	      uint64_t frame_energy = 0;
286	      uint32_t frame_peak = 0;
287	
288	      if ((nread & 1) != 0)
289	        {
290	          close(fd);
291	          return -EINVAL;
292	        }
293	
294	      count = nread / sizeof(samples[0]);
295	      for (i = 0; i < count; i++)
296	        {
297	          int32_t sample = samples[i];
298	          uint32_t magnitude = sample < 0 ? -sample : sample;
299	
300	          if (magnitude > frame_peak)
301	            {
302	              frame_peak = magnitude;
303	            }
304	
305	          frame_energy += (uint64_t)(sample * sample);
306	        }
307	
308	      if (frame_peak > metrics->peak)
309	        {
310	          metrics->peak = frame_peak;
311	        }
312	
313	      if (frame_peak >= KWS_CAPTURE_MIN_PEAK &&
314	          frame_energy / count >= KWS_CAPTURE_MIN_RMS * KWS_CAPTURE_MIN_RMS)
315	        {
316	          metrics->active_frames++;
317	        }
318	
319	      metrics->sum_squares += frame_energy;
320	      metrics->samples += count;
321	      metrics->frames++;
322	      metrics->bytes += nread;
323	    }
324	
325	  if (nread < 0)
326	    {
327	      int ret = -errno;
328	      close(fd);
329	      return ret;
330	    }
331	
332	  close(fd);
333	  if (metrics->samples == 0)
334	    {
335	      return -ENODATA;
336	    }
337	
338	  metrics->rms = kws_capture_isqrt(metrics->sum_squares / metrics->samples);
339	  return OK;
340	}
