689	    "按 Enter 开始录音，输入 q 结束本批次：");
690	  if (choice == 'q' || g_kws_capture_cancelled)
691	    {
692	      return -ECANCELED;
693	    }
694	  else if (choice < 0)
695	    {
696	      return choice;
697	    }
698	
699	  printf("3\n");
700	  sleep(1);
701	  printf("2\n");
702	  sleep(1);
703	  printf("1\n");
704	  sleep(1);
705	  if (g_kws_capture_cancelled)
706	    {
707	      return -ECANCELED;
708	    }
709	
710	  ret = kws_capture_reserve_part(pcm_part);
711	  if (ret < 0)
712	    {
713	      return ret;
714	    }
715	
716	  printf("正在录制 %s ...\n", sample_id);
717	  ret = kws_capture_record(options->capture_device, pcm_part,
718	                           options->record_ms);
719	  if (ret < 0)
720	    {
721	      unlink(pcm_part);
722	      return ret;
723	    }
724	
725	  ret = kws_capture_measure(pcm_part, &metrics);
726	  if (ret < 0)
727	    {
728	      unlink(pcm_part);
729	      return ret;
730	    }
731	
732	  if (metrics.samples * 1000 <
733	        (uint64_t)(options->record_ms - KWS_CAPTURE_DURATION_TOLERANCE) *
734	        KWS_CAPTURE_SAMPLE_RATE ||
735	      metrics.samples * 1000 >
736	        ((uint64_t)options->record_ms + KWS_CAPTURE_DURATION_TOLERANCE) *
737	        KWS_CAPTURE_SAMPLE_RATE)
738	    {
739	      printf("录音长度超出容差：%llu ms\n",
740	             (unsigned long long)(metrics.samples * 1000 /
741	                                  KWS_CAPTURE_SAMPLE_RATE));
742	      unlink(pcm_part);
743	      return -EIO;
744	    }
745	
746	  printf("bytes=%llu duration=%llu ms peak=%lu rms=%lu active=%lu/%lu\n",
747	         (unsigned long long)metrics.bytes,
748	         (unsigned long long)(metrics.samples * 1000 /
749	                              KWS_CAPTURE_SAMPLE_RATE),
750	         (unsigned long)metrics.peak, (unsigned long)metrics.rms,
751	         (unsigned long)metrics.active_frames, (unsigned long)metrics.frames);
752	  printf("正在回放本次录音，请试听后选择。\n");
753	  fflush(stdout);
754	  ret = kws_capture_playback(options, pcm_part,
755	                             metrics.samples * 1000 /
756	                             KWS_CAPTURE_SAMPLE_RATE);
757	  if (ret < 0)
758	    {
759	      fprintf(stderr, "kws capture: playback failed: %d\n", ret);
760	      unlink(pcm_part);
761	      return ret;
762	    }
763	
764	  choice = kws_capture_read_choice(
765	    "Enter/k 保留，r 重录，q 丢弃并退出：");
766	  if (choice == 'r')
767	    {
768	      unlink(pcm_part);
769	      return -EAGAIN;
770	    }
771	  else if (choice == 'q' || g_kws_capture_cancelled)
772	    {
773	      unlink(pcm_part);
774	      return -ECANCELED;
775	    }
776	  else if (choice != 'k')
777	    {
778	      printf("无效选择，当前样本未保存。\n");
779	      unlink(pcm_part);
780	      return -EAGAIN;
781	    }
782	
783	  ret = kws_capture_write_metadata(json_part, options, sample_id, take,
784	                                   &metrics);
785	  if (ret < 0)
786	    {
787	      unlink(pcm_part);
788	      return ret;
789	    }
790	
791	  ret = kws_capture_publish_pair(pcm_part, json_part, pcm_path, json_path);
792	  if (ret < 0)
793	    {
794	      unlink(pcm_part);
795	      unlink(json_part);
796	      return ret;
797	    }
798	
799	  printf("已保存：%s.pcm + .json\n", sample_id);
800	  return OK;
801	}
