803	static uint16_t kws_capture_first_take(FAR const struct kws_capture_options_s *options,
804	                                       FAR const char *directory)
805	{
806	  char sample_id[32];
807	  char path[PATH_MAX];
808	  uint16_t take;
809	
810	  for (take = 1; take < UINT16_MAX; take++)
811	    {
812	      int length;
813	
814	      if (kws_capture_sample_id(options, take, sample_id,
815	                                sizeof(sample_id)) < 0)
816	        {
817	          return 0;
818	        }
819	
820	      length = snprintf(path, sizeof(path), "%s/%s.pcm", directory,
821	                        sample_id);
822	      if (length < 0 || (size_t)length >= sizeof(path))
823	        {
824	          fprintf(stderr, "kws capture: sample path exceeds PATH_MAX=%u\n",
825	                  (unsigned int)PATH_MAX);
826	          return 0;
827	        }
828	
829	      if (access(path, F_OK) < 0 && errno == ENOENT)
830	        {
831	          return take;
832	        }
833	    }
834	
835	  return 0;
836	}
