838	int kws_capture_run(FAR const struct kws_capture_options_s *options)
839	{
840	  struct sigaction action;
841	  struct sigaction old_int;
842	  struct sigaction old_term;
843	  char directory[PATH_MAX];
844	  uint16_t completed = 0;
845	  uint16_t take;
846	  int ret;
847	
848	  printf("kws capture: starting label=%s speaker=%s session=%s\n",
849	         options != NULL && options->label != NULL ? options->label : "(null)",
850	         options != NULL && options->speaker_id != NULL ?
851	           options->speaker_id : "(null)",
852	         options != NULL && options->session_id != NULL ?
853	           options->session_id : "(null)");
854	  fflush(stdout);
855	
856	  ret = kws_capture_validate_options(options);
857	  if (ret < 0)
858	    {
859	      fprintf(stderr, "kws capture: invalid options: %d\n", ret);
860	      return ret;
861	    }
862	
863	  ret = kws_capture_make_directory(options->output_root);
864	  if (ret < 0)
865	    {
866	      fprintf(stderr, "kws capture: cannot prepare %s: %d\n",
867	              options->output_root, ret);
868	      return ret;
869	    }
870	
871	  if (snprintf(directory, sizeof(directory), "%s/%s", options->output_root,
872	               options->session_id) >= sizeof(directory))
873	    {
874	      return -ENAMETOOLONG;
875	    }
876	
877	  ret = kws_capture_make_directory(directory);
878	  if (ret < 0)
879	    {
880	      fprintf(stderr, "kws capture: cannot prepare %s: %d\n", directory, ret);
881	      return ret;
882	    }
883	
884	  ret = kws_capture_check_storage(directory, options->record_ms,
885	                                  options->count);
886	  if (ret < 0)
887	    {
888	      return ret;
889	    }
890	
891	  take = kws_capture_first_take(options, directory);
892	  if (take == 0)
893	    {
894	      fprintf(stderr, "kws capture: no unused take number in %s\n", directory);
895	      return -ENOSPC;
896	    }
897	
898	  memset(&action, 0, sizeof(action));
899	  action.sa_handler = kws_capture_signal_handler;
900	  sigemptyset(&action.sa_mask);
901	  g_kws_capture_cancelled = 0;
902	  sigaction(SIGINT, &action, &old_int);
903	  sigaction(SIGTERM, &action, &old_term);
904	
905	  printf("R528 中文 KWS 语料采集\n");
906	  printf("label=%s speaker=%s session=%s count=%u record_ms=%lu\n",
907	         options->label, options->speaker_id, options->session_id,
908	         options->count, (unsigned long)options->record_ms);
909	  printf("输出目录：%s\n", directory);
910	
911	  while (completed < options->count && !g_kws_capture_cancelled)
912	    {
913	      ret = kws_capture_one(options, directory, take);
914	      if (ret == -EAGAIN)
915	        {
916	          continue;
917	        }
918	      else if (ret == -EEXIST)
919	        {
920	          take++;
921	          continue;
922	        }
923	      else if (ret == -ECANCELED)
924	        {
925	          break;
926	        }
927	      else if (ret < 0)
928	        {
929	          fprintf(stderr, "kws capture: sample %u failed: %d\n", take, ret);
930	          break;
931	        }
932	
933	      completed++;
934	      take++;
935	    }
936	
937	  sigaction(SIGINT, &old_int, NULL);
938	  sigaction(SIGTERM, &old_term, NULL);
939	  printf("采集结束：已保存 %u/%u 条。\n", completed, options->count);
940	  if (g_kws_capture_cancelled || ret == -ECANCELED)
941	    {
942	      return completed > 0 ? OK : -ECANCELED;
943	    }
944	
945	  return ret < 0 ? ret : OK;
946	}
