134	static int routine_parse_uint(const char *text, unsigned int minimum,
135	                              unsigned int maximum, unsigned int *value)
136	{
137	  char *end;
138	  unsigned long parsed;
139	
140	  errno = 0;
141	  parsed = strtoul(text, &end, 10);
142	  if (errno != 0 || *text == '\0' || *end != '\0' ||
143	      parsed < minimum || parsed > maximum)
144	    {
145	      return -EINVAL;
146	    }
147	
148	  *value = parsed;
149	  return 0;
150	}
