165	static int routine_parse_options(int argc, FAR char *argv[],
166	                                 struct routine_options_s *options)
167	{
168	  unsigned int value;
169	  int i;
170	  int ret;
171	
172	  memset(options, 0, sizeof(*options));
173	  options->font_path = CONFIG_ROUTINE_MANAGER_FONT_PATH;
174	  options->rate = CONFIG_ROUTINE_MANAGER_DEMO_RATE;
175	  options->language = ROUTINE_UI_LANGUAGE_CHINESE;
176	#ifdef CONFIG_ROUTINE_MANAGER_KWS_CAPTURE
177	  options->capture.device_id = CONFIG_ROUTINE_MANAGER_KWS_DEVICE_ID;
178	  options->capture.capture_device =
179	    CONFIG_ROUTINE_MANAGER_VOICE_CAPTURE_DEVICE;
180	  options->capture.playback_device =
181	    CONFIG_ROUTINE_MANAGER_VOICE_PLAYBACK_DEVICE;
182	  options->capture.output_root = CONFIG_ROUTINE_MANAGER_KWS_CAPTURE_ROOT;
183	  options->capture.record_ms = CONFIG_ROUTINE_MANAGER_VOICE_RECORD_MS;
184	  options->capture.playback_volume = CONFIG_ROUTINE_MANAGER_VOICE_VOLUME;
185	  options->capture.count = 20;
186	#endif
187	
188	  for (i = 1; i < argc; i++)
189	    {
190	      if (strcmp(argv[i], "--demo") == 0)
191	        {
192	          options->demo = true;
193	        }
194	      else if (strcmp(argv[i], "--chinese") == 0)
195	        {
196	          ret = routine_set_language(options, ROUTINE_UI_LANGUAGE_CHINESE);
197	          if (ret < 0)
198	            {
199	              fprintf(stderr,
200	                      "routine_mgr: conflicting language option: %s\n",
201	                      argv[i]);
202	              return ret;
203	            }
204	        }
205	      else if (strcmp(argv[i], "--english") == 0 ||
206	               strcmp(argv[i], "--ascii") == 0)
207	        {
208	          ret = routine_set_language(options, ROUTINE_UI_LANGUAGE_ENGLISH);
209	          if (ret < 0)
210	            {
211	              fprintf(stderr,
212	                      "routine_mgr: conflicting language option: %s\n",
213	                      argv[i]);
214	              return ret;
215	            }
216	        }
217	      else if (strcmp(argv[i], "--selftest") == 0)
218	        {
219	          options->selftest = true;
220	        }
221	      else if (strcmp(argv[i], "--help") == 0)
222	        {
223	          routine_usage();
224	          return 1;
225	        }
226	      else if (strcmp(argv[i], "--font") == 0 && i + 1 < argc)
227	        {
228	          options->font_path = argv[++i];
229	          options->font_set = true;
230	        }
231	      else if (strcmp(argv[i], "--rate") == 0 && i + 1 < argc)
232	        {
233	          ret = routine_parse_uint(argv[++i], 1, 60, &value);
234	          if (ret < 0)
235	            {
236	              return ret;
237	            }
238	
239	          options->rate = value;
240	          options->rate_set = true;
241	        }
242	      else if (strcmp(argv[i], "--duration") == 0 && i + 1 < argc)
243	        {
244	          ret = routine_parse_uint(argv[++i], 1, 86400, &value);
245	          if (ret < 0)
246	            {
247	              return ret;
248	            }
249	
250	          options->duration = value;
251	        }
252	#ifdef CONFIG_ROUTINE_MANAGER_KWS_CAPTURE
253	      else if (strcmp(argv[i], "-K") == 0 ||
254	               strcmp(argv[i], "--kws-capture") == 0)
255	        {
256	          options->kws_capture = true;
257	        }
258	      else if ((strcmp(argv[i], "-l") == 0 ||
259	                strcmp(argv[i], "--label") == 0) && i + 1 < argc)
260	        {
261	          options->capture.label = argv[++i];
262	        }
263	      else if ((strcmp(argv[i], "-p") == 0 ||
264	                strcmp(argv[i], "--speaker") == 0) && i + 1 < argc)
265	        {
266	          options->capture.speaker_id = argv[++i];
267	        }
268	      else if ((strcmp(argv[i], "-s") == 0 ||
269	                strcmp(argv[i], "--session") == 0) && i + 1 < argc)
270	        {
271	          options->capture.session_id = argv[++i];
272	        }
273	      else if ((strcmp(argv[i], "-i") == 0 ||
274	                strcmp(argv[i], "--device-id") == 0) && i + 1 < argc)
275	        {
276	          options->capture.device_id = argv[++i];
277	        }
278	      else if ((strcmp(argv[i], "-n") == 0 ||
279	                strcmp(argv[i], "--count") == 0) && i + 1 < argc)
280	        {
281	          ret = routine_parse_uint(argv[++i], 1, 1000, &value);
282	          if (ret < 0)
283	            {
284	              return ret;
285	            }
286	
287	          options->capture.count = value;
288	        }
289	      else if ((strcmp(argv[i], "-m") == 0 ||
290	                strcmp(argv[i], "--record-ms") == 0) && i + 1 < argc)
291	        {
292	          ret = routine_parse_uint(argv[++i], 1000, 10000, &value);
293	          if (ret < 0)
294	            {
