461	static int routine_get_local_clock(struct routine_clock_s *clock)
462	{
463	  struct tm utc_time;
464	  struct tm civil_time;
465	  time_t civil_wall_time;
466	  time_t wall_time;
467	
468	  if (clock == NULL)
469	    {
470	      return -EINVAL;
471	    }
472	
473	  wall_time = time(NULL);
474	  if (wall_time < 0 || gmtime_r(&wall_time, &utc_time) == NULL ||
475	      utc_time.tm_year + 1900 < 2020)
476	    {
477	      memset(clock, 0, sizeof(*clock));
478	      return -ENODATA;
479	    }
480	
481	  civil_wall_time = wall_time +
482	                    CONFIG_ROUTINE_MANAGER_UTC_OFFSET_MINUTES * 60;
483	  if (gmtime_r(&civil_wall_time, &civil_time) == NULL)
484	    {
485	      memset(clock, 0, sizeof(*clock));
486	      return -ENODATA;
487	    }
488	
489	  clock->day = civil_wall_time / (24 * 60 * 60);
490	  clock->hour = civil_time.tm_hour;
491	  clock->minute = civil_time.tm_min;
492	  clock->valid = true;
493	  return OK;
494	}
