496	static void routine_dispatch_due(struct routine_app_s *app)
497	{
498	  struct routine_due_event_s event;
499	
500	  while (routine_model_take_due(&app->model, &event) == OK)
501	    {
502	      int ui_ret = routine_ui_enqueue_due(&event);
503	
504	      if (ui_ret < 0 && ui_ret != -EALREADY)
505	        {
506	          syslog(LOG_ERR,
507	                 "routine_mgr: due UI queue id=%u failed: %d\n",
508	                 event.schedule_id, ui_ret);
509	        }
510	
511	#ifdef CONFIG_ROUTINE_MANAGER_VOICE
512	      if (app->audio_started)
513	        {
514	          struct audio_service_reminder_s reminder;
515	          int audio_ret;
516	
517	          reminder.sequence = event.sequence;
518	          reminder.schedule_id = event.schedule_id;
519	          reminder.text_id = event.text_id;
520	          reminder.hour = event.hour;
521	          reminder.minute = event.minute;
522	          audio_ret = audio_service_enqueue_reminder(&app->audio, &reminder);
523	          if (audio_ret < 0 && audio_ret != -EALREADY)
524	            {
525	              syslog(LOG_ERR,
526	                     "routine_mgr: due audio queue id=%u failed: %d\n",
527	                     event.schedule_id, audio_ret);
528	            }
529	        }
530	#endif
531	    }
532	}
