534	static void routine_timer_cb(lv_timer_t *timer)
535	{
536	  struct routine_app_s *app = lv_timer_get_user_data(timer);
537	  struct environment_sample_s environment;
538	  struct routine_clock_s clock;
539	
540	  if (app->model.clock_mode == ROUTINE_CLOCK_DEMO)
541	    {
542	      routine_model_tick_demo(&app->model);
543	    }
544	  else if (routine_get_local_clock(&clock) == OK)
545	    {
546	      time_t wall_time = time(NULL);
547	      int clock_ret;
548	
549	      if (app->last_wall_time != 0 &&
550	          (wall_time < app->last_wall_time ||
551	           wall_time - app->last_wall_time > ROUTINE_CLOCK_REBASE_SECONDS))
552	        {
553	          routine_model_clear_due(&app->model);
554	          routine_model_init_live(&app->model, &clock);
555	          clock_ret = ROUTINE_CLOCK_REBASED;
556	        }
557	      else
558	        {
559	          clock_ret = routine_model_update_clock(&app->model, &clock);
560	        }
561	
562	      app->last_wall_time = wall_time;
563	      if (clock_ret == ROUTINE_CLOCK_REBASED)
564	        {
565	          routine_ui_clear_due();
566	#ifdef CONFIG_ROUTINE_MANAGER_VOICE
567	          if (app->audio_started)
568	            {
569	              audio_service_clear_reminders(&app->audio);
570	            }
571	#endif
572	        }
573	    }
574	  if (app->environment_started &&
575	      environment_service_get_sample(&app->environment, &environment) == 0)
576	    {
577	      routine_model_apply_environment(&app->model, &environment);
578	    }
579	
580	  routine_dispatch_due(app);
581	  routine_ui_update(routine_model_get_snapshot(&app->model));
582	  routine_update_audio_sensors(app);
583	}
