621	static int routine_schedule_action_cb(
622	  void *user_data, uint8_t schedule_id, uint32_t due_sequence,
623	  enum routine_schedule_action_e action)
624	{
625	  struct routine_due_event_s ended_due;
626	  struct routine_app_s *app = user_data;
627	  int ret;
628	
629	  if (app == NULL)
630	    {
631	      return -EINVAL;
632	    }
633	
634	  memset(&ended_due, 0, sizeof(ended_due));
635	  ret = routine_model_apply_schedule_action(&app->model, schedule_id,
636	                                            due_sequence, action,
637	                                            &ended_due);
638	  if (ret == -ESTALE && due_sequence != 0)
639	    {
640	      memset(&ended_due, 0, sizeof(ended_due));
641	      ended_due.sequence = due_sequence;
642	      ended_due.schedule_id = schedule_id;
643	      ret = OK;
644	    }
645	  else if (ret < 0)
646	    {
647	      syslog(LOG_ERR,
648	             "routine_mgr: schedule action=%u id=%u sequence=%lu failed: %d\n",
649	             action, schedule_id, (unsigned long)due_sequence, ret);
650	      return ret;
651	    }
652	
653	  if (ended_due.sequence != 0)
654	    {
655	      routine_ui_remove_due(&ended_due);
656	#ifdef CONFIG_ROUTINE_MANAGER_VOICE
657	      if (app->audio_started)
658	        {
659	          struct audio_service_reminder_s reminder;
660	
661	          memset(&reminder, 0, sizeof(reminder));
662	          reminder.sequence = ended_due.sequence;
663	          reminder.schedule_id = ended_due.schedule_id;
664	          reminder.text_id = ended_due.text_id;
665	          reminder.hour = ended_due.hour;
666	          reminder.minute = ended_due.minute;
667	          audio_service_cancel_reminder(&app->audio, &reminder);
668	        }
669	#endif
670	    }
671	
672	  routine_ui_update(routine_model_get_snapshot(&app->model));
673	  return OK;
674	}
