47	                CONFIG_R528_SDHC_AUTOMOUNT_MOUNTPOINT,
48	                CONFIG_R528_SDHC_AUTOMOUNT_FSTYPE, MS_NOSUID|MS_SYNCHRONOUS, NULL);
